import SwiftUI
struct DashboardView:View { @EnvironmentObject var s:TradingStore; var body:some View { NavigationStack { ScrollView { VStack(spacing:16){ HStack{VStack(alignment:.leading){Text("NEXER QUANT").font(.title.bold());Text(s.settings.autoEnabled ? "AUTO ACTIVE" : "AUTO OFF").foregroundStyle(s.settings.autoEnabled ? .green:.secondary)};Spacer();Toggle("",isOn:$s.settings.autoEnabled).labelsHidden()}.padding(); metric("Paper Equity",s.equity.formatted(.currency(code:"USD"))); metric("Cash",s.cash.formatted(.currency(code:"USD"))); metric("Open Positions","\(s.positions.count) / \(s.settings.maxPositions)"); Button(s.isScanning ? "Scanning…" : "SCAN MARKET + RUN AUTO"){Task{await s.scan()}}.buttonStyle(.borderedProminent).disabled(s.isScanning); if let b=s.scans.first { VStack(alignment:.leading,spacing:7){Text("BEST SETUP").font(.caption).foregroundStyle(.secondary);Text("\(b.asset.symbol)  \(b.score)/100").font(.title2.bold());Text(b.reason).font(.footnote)}.frame(maxWidth:.infinity,alignment:.leading).padding().background(.thinMaterial,in:RoundedRectangle(cornerRadius:16)) } }.padding() }.navigationTitle("Auto Trader") } }
 func metric(_ a:String,_ b:String)->some View{HStack{Text(a);Spacer();Text(b).bold()}.padding().background(.thinMaterial,in:RoundedRectangle(cornerRadius:14))}
}
